pub(crate) fn locale(lang: &str, script: &str, region: &str) -> &'static str {
    match (lang, script, region) {
        ("en", _, "IN") => "en-IN",
        ("pt", _, "PT") => "pt-PT",
        ("zh", "Hant", _) | ("zh", _, "TW" | "HK" | "MO") => "zh-Hant",
        _ => match lang {
            "en" => "en",
            "de" => "de",
            "fr" => "fr",
            "es" => "es",
            "it" => "it",
            "pt" => "pt",
            "nl" => "nl",
            "ja" => "ja",
            "zh" => "zh",
            "ko" => "ko",
            "ru" => "ru",
            "ar" => "ar",
            "sr" => "sr",
            "th" => "th",
            "gv" => "gv",
            "sl" => "sl",
            "pl" => "pl",
            "si" => "si",
            "ln" => "ln",
            "sv" => "sv",
            "hi" => "hi",
            _ => "en",
        },
    }
}

fn styles(locale: &str) -> Styles {
    match locale {
        "en" => ST_EN,
        "en-IN" => ST_EN_IN,
        "de" => ST_DE,
        "fr" => ST_FR,
        "es" => ST_ES,
        "it" => ST_IT,
        "pt" => ST_PT,
        "pt-PT" => ST_PT_PT,
        "nl" => ST_NL,
        "ja" => ST_JA,
        "zh" => ST_ZH,
        "zh-Hant" => ST_ZH_HANT,
        "ko" => ST_KO,
        "ru" => ST_RU,
        "ar" => ST_AR,
        "sr" => ST_SR,
        "th" => ST_TH,
        "gv" => ST_GV,
        "sl" => ST_SL,
        "pl" => ST_PL,
        "si" => ST_SI,
        "ln" => ST_LN,
        "sv" => ST_SV,
        "hi" => ST_HI,
        _ => ST_EN,
    }
}

fn style_index(style: &str) -> usize {
    match style { "full" => 0, "long" => 1, "medium" => 2, _ => 3 }
}

pub(crate) fn date_style(locale: &str, style: &str) -> &'static str {
    styles(locale).dates[style_index(style)]
}

pub(crate) fn time_style(locale: &str, style: &str) -> &'static str {
    styles(locale).times[style_index(style)]
}

pub(crate) fn connector(locale: &str, style: &str) -> &'static str {
    styles(locale).connectors[style_index(style)]
}

pub(crate) fn range_fallback(locale: &str) -> &'static str { styles(locale).fallback }
pub(crate) fn default_hour_cycle(locale: &str) -> &'static str { styles(locale).hour_cycle }

fn available_rows(locale: &str) -> &'static [(&'static str, &'static str)] {
    match locale {
        "en" => AV_EN,
        "en-IN" => AV_EN_IN,
        "de" => AV_DE,
        "fr" => AV_FR,
        "es" => AV_ES,
        "it" => AV_IT,
        "pt" => AV_PT,
        "pt-PT" => AV_PT_PT,
        "nl" => AV_NL,
        "ja" => AV_JA,
        "zh" => AV_ZH,
        "zh-Hant" => AV_ZH_HANT,
        "ko" => AV_KO,
        "ru" => AV_RU,
        "ar" => AV_AR,
        "sr" => AV_SR,
        "th" => AV_TH,
        "gv" => AV_GV,
        "sl" => AV_SL,
        "pl" => AV_PL,
        "si" => AV_SI,
        "ln" => AV_LN,
        "sv" => AV_SV,
        "hi" => AV_HI,
        _ => AV_EN,
    }
}

pub(crate) fn available(locale: &str) -> &'static [(&'static str, &'static str)] {
    available_rows(locale)
}

pub(crate) fn available_exact(locale: &str, skeleton: &str) -> Option<&'static str> {
    let rows = available_rows(locale);
    rows.binary_search_by_key(&skeleton, |row| row.0).ok().map(|index| rows[index].1)
}

